solution.code:
def min_subarray_len(target, nums):
    best = 0
    left = 0
    total = 0
    for right, x in enumerate(nums):
        total += x
        while total >= target:
            width = right - left + 1
            if best == 0 or width < best:
                best = width
            total -= nums[left]
            left += 1
    return best

