    # brute force is three nested loops; what does sorting buy you?
    pass

solution.code:
def three_sum_smaller(nums, target):
    s = sorted(nums)
    count = 0
    for i in range(len(s) - 2):
        left, right = i + 1, len(s) - 1
        while left < right:
            if s[i] + s[left] + s[right] < target:
                count += right - left
                left += 1
            else:
                right -= 1
    return count

